/// <summary>
/// PaffH 19.01.21
/// find NDXDuty2PrivilegeTable
/// </summary>
/// <param name = "_RefRecIdNDXDutyTable">RefRecId</param>
/// <param name = "_RefRecIdNDXPrivilegeTable">RefRecId</param>
/// <param name = "_forUpdate">boolean</param>
/// <returns>NDXDuty2PrivilegeTable</returns>
static NDXDuty2PrivilegeTable find(RefRecId _RefRecIdNDXDutyTable, RefRecId _RefRecIdNDXPrivilegeTable, boolean _forUpdate = true)
{
    NDXDuty2PrivilegeTable nDXDuty2PrivilegeTable;
    nDXDuty2PrivilegeTable.selectForUpdate(_forUpdate);
    select nDXDuty2PrivilegeTable
        where nDXDuty2PrivilegeTable.RefRecIdNDXDutyTable == _RefRecIdNDXDutyTable
        &&  nDXDuty2PrivilegeTable.RefRecIdNDXPrivilegeTable == _RefRecIdNDXPrivilegeTable;
    return nDXDuty2PrivilegeTable;
}

/// <summary>
/// PaffH 19.01.21
/// find or create NDXDuty2PrivilegeTable
/// </summary>
/// <param name = "_RefRecIdNDXDutyTable">RefRecId</param>
/// <param name = "_RefRecIdNDXPrivilegeTable">RefRecId</param>
/// <param name = "_insert">boolean</param>
/// <returns>NDXDuty2PrivilegeTable</returns>
static NDXDuty2PrivilegeTable findOrCreate(RefRecId _RefRecIdNDXDutyTable, RefRecId _RefRecIdNDXPrivilegeTable, boolean _insert = true)
{
    NDXDuty2PrivilegeTable nDXDuty2PrivilegeTable;
    nDXDuty2PrivilegeTable = NDXDuty2PrivilegeTable::find(_RefRecIdNDXDutyTable, _RefRecIdNDXPrivilegeTable, true);
    if (!nDXDuty2PrivilegeTable)
    {
        nDXDuty2PrivilegeTable.RefRecIdNDXDutyTable = _RefRecIdNDXDutyTable;
        nDXDuty2PrivilegeTable.RefRecIdNDXPrivilegeTable = _RefRecIdNDXPrivilegeTable;
        if (_insert)
        {
            nDXDuty2PrivilegeTable.insert();
        }
    }
    return nDXDuty2PrivilegeTable;
}

/// <summary>
/// PaffH 20.01.21
/// delete records not updated
/// </summary>
/// <param name = "_updatedUtcDateTime">NDXUpdatedUTCDateTime</param>
/// <param name = "_logger">NDXLoggerSecurityInformationClass</param>
/// <returns>counter deleted records</returns>
static public int deleteNotUpdated(NDXUpdatedUTCDateTime _updatedUtcDateTime, NDXLoggerSecurityInformationClass _logger)
{
    NDXDuty2PrivilegeTable nDXDuty2PrivilegeTable;

    NDXArgsLoggerSecuritiyInformation argsLogger = new NDXArgsLoggerSecuritiyInformation();
    argsLogger.parmLogActivity(strFmt("@NDX:NDXDeleteRecordsInTable", tableId2PName(nDXDuty2PrivilegeTable.TableId)));
    _logger.LogLineCreate(argsLogger);

    NDXHelperTable::skipForDelete(nDXDuty2PrivilegeTable);
    delete_from nDXDuty2PrivilegeTable
        where nDXDuty2PrivilegeTable.UpdatedUTCDateTime != _updatedUtcDateTime;

    argsLogger.parmCounter(int642int(nDXDuty2PrivilegeTable.RowCount()));
    _logger.LogLineChange(argsLogger);

    return int642int(nDXDuty2PrivilegeTable.RowCount());
}
